-- postrust-ai: job queue, workflows, sessions, nodes and result cache.
--
-- Everything lives in the `ai` schema so it can be exposed through Postrust's
-- own REST API (add `ai` to the exposed schemas) or kept out of it, as a unit.
--
-- Idempotent: every statement is IF NOT EXISTS / OR REPLACE, so a node can
-- apply it on every start. Concurrent starts are serialised by the caller with
-- an advisory lock -- CREATE ... IF NOT EXISTS is not race-safe on its own.
--
-- IDs are generated by the application rather than by gen_random_uuid(), which
-- keeps this file working on PostgreSQL 12 without pgcrypto.

CREATE SCHEMA IF NOT EXISTS ai;

-- ---------------------------------------------------------------------------
-- Queues
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ai.queues (
    name                text PRIMARY KEY,
    -- Worker slots per node, not across the cluster.
    concurrency         integer NOT NULL DEFAULT 4 CHECK (concurrency > 0),
    -- What a pause does to a running job: `checkpoint` keeps its progress,
    -- `requeue` throws it away and starts again later.
    pause_mode          text NOT NULL DEFAULT 'checkpoint'
                        CHECK (pause_mode IN ('checkpoint', 'requeue')),
    -- How long a checkpointing job gets to stop on its own before it is
    -- cancelled and requeued from its last saved checkpoint.
    pause_grace_secs    integer NOT NULL DEFAULT 30 CHECK (pause_grace_secs >= 0),
    max_attempts        integer NOT NULL DEFAULT 3 CHECK (max_attempts > 0),
    retry_backoff_secs  integer NOT NULL DEFAULT 10 CHECK (retry_backoff_secs >= 0),
    result_cache        boolean NOT NULL DEFAULT false,
    -- A paused queue hands out no jobs; running ones finish.
    paused              boolean NOT NULL DEFAULT false,
    updated_at          timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- Jobs
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ai.jobs (
    id                  uuid PRIMARY KEY,
    queue               text NOT NULL REFERENCES ai.queues (name),
    model_id            text NOT NULL,
    priority_class      text NOT NULL
                        CHECK (priority_class IN ('critical', 'high', 'normal', 'low', 'superlow')),
    -- Derived from the class at enqueue time, plus the caller's offset within
    -- it. Claims order by this, adjusted for age.
    priority            integer NOT NULL,
    status              text NOT NULL DEFAULT 'queued'
                        CHECK (status IN ('queued', 'running', 'paused', 'completed',
                                          'failed', 'cancelled', 'dead')),
    -- Why a paused job is paused. `preempted` jobs resume by themselves when
    -- there is capacity again; `manual` ones wait for a resume call.
    pause_reason        text CHECK (pause_reason IN ('preempted', 'manual')),
    -- Set by anyone (another node, the API) to ask the worker running this job
    -- to pause. The worker sees it on its next heartbeat.
    pause_requested     boolean NOT NULL DEFAULT false,
    cancel_requested    boolean NOT NULL DEFAULT false,
    input               jsonb NOT NULL,
    params              jsonb NOT NULL DEFAULT '{}'::jsonb,
    output              jsonb,
    error               text,
    checkpoint          jsonb,
    attempts            integer NOT NULL DEFAULT 0,
    max_attempts        integer NOT NULL,
    preemptions         integer NOT NULL DEFAULT 0,
    idempotency_key     text UNIQUE,
    cache_hit           boolean NOT NULL DEFAULT false,
    workflow_run_id     uuid,
    workflow_step       text,
    worker_node         text,
    lease_expires_at    timestamptz,
    run_at              timestamptz NOT NULL DEFAULT now(),
    created_at          timestamptz NOT NULL DEFAULT now(),
    started_at          timestamptz,
    finished_at         timestamptz,
    updated_at          timestamptz NOT NULL DEFAULT now()
);

-- The claim path. Partial, so the index stays the size of the backlog rather
-- than the size of history.
CREATE INDEX IF NOT EXISTS jobs_claimable
    ON ai.jobs (queue, priority DESC, run_at)
    WHERE status = 'queued' OR (status = 'paused' AND pause_reason = 'preempted');

-- The lease reaper.
CREATE INDEX IF NOT EXISTS jobs_running_lease
    ON ai.jobs (lease_expires_at)
    WHERE status = 'running';

CREATE INDEX IF NOT EXISTS jobs_workflow_run
    ON ai.jobs (workflow_run_id)
    WHERE workflow_run_id IS NOT NULL;

-- Heartbeats rewrite the row every few seconds. Vacuum this table far more
-- eagerly than the default 20% of dead tuples, or a busy queue bloats.
ALTER TABLE ai.jobs SET (
    autovacuum_vacuum_scale_factor = 0.01,
    autovacuum_analyze_scale_factor = 0.02,
    fillfactor = 80
);

-- Finished jobs are moved here so `ai.jobs` holds only live work.
CREATE TABLE IF NOT EXISTS ai.jobs_archive (LIKE ai.jobs INCLUDING DEFAULTS);
CREATE INDEX IF NOT EXISTS jobs_archive_created ON ai.jobs_archive (created_at);
CREATE INDEX IF NOT EXISTS jobs_archive_workflow_run
    ON ai.jobs_archive (workflow_run_id)
    WHERE workflow_run_id IS NOT NULL;

-- Wake workers when a job becomes claimable. A trigger rather than a
-- pg_notify() in each statement, so every path that requeues a job -- retry,
-- preemption, lease expiry, a hand-written UPDATE -- wakes them the same way.
-- The payload is the queue name; NOTIFY collapses duplicates within a
-- transaction, so a batch insert sends one per queue.
CREATE OR REPLACE FUNCTION ai.notify_job_ready() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.status = 'queued'
       OR (NEW.status = 'paused' AND NEW.pause_reason = 'preempted') THEN
        PERFORM pg_notify('postrust_ai_jobs', NEW.queue);
    END IF;
    RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS jobs_notify_ready ON ai.jobs;
CREATE TRIGGER jobs_notify_ready
    AFTER INSERT OR UPDATE OF status ON ai.jobs
    FOR EACH ROW EXECUTE FUNCTION ai.notify_job_ready();

-- ---------------------------------------------------------------------------
-- Workflows
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ai.workflows (
    name        text PRIMARY KEY,
    definition  jsonb NOT NULL,
    version     integer NOT NULL DEFAULT 1,
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS ai.workflow_runs (
    id              uuid PRIMARY KEY,
    workflow        text NOT NULL,
    -- The definition as it was when the run started, so editing a workflow
    -- does not change runs already in flight.
    definition      jsonb NOT NULL,
    status          text NOT NULL DEFAULT 'running'
                    CHECK (status IN ('running', 'completed', 'failed', 'cancelled')),
    input           jsonb NOT NULL,
    -- Per-step status and outputs. Derived from the step jobs and rewritten by
    -- every advance, so it can always be rebuilt from `ai.jobs`.
    state           jsonb NOT NULL DEFAULT '{}'::jsonb,
    output          jsonb,
    error           text,
    queue           text NOT NULL,
    priority_class  text NOT NULL,
    created_at      timestamptz NOT NULL DEFAULT now(),
    finished_at     timestamptz,
    updated_at      timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS workflow_runs_running
    ON ai.workflow_runs (updated_at)
    WHERE status = 'running';

-- ---------------------------------------------------------------------------
-- Nodes and sessions
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ai.nodes (
    node_id     text PRIMARY KEY,
    base_url    text NOT NULL,
    -- Budget and use, as last reported.
    resources   jsonb NOT NULL DEFAULT '{}'::jsonb,
    -- Model ids with a ready instance on this node.
    ready_models text[] NOT NULL DEFAULT '{}',
    started_at  timestamptz NOT NULL DEFAULT now(),
    last_seen   timestamptz NOT NULL DEFAULT now()
);

-- A session lock: every request carrying this session id for this model goes
-- to the same model instance, and that instance is not unloaded while the lock
-- is live. That is what makes server-side prompt and KV caches useful.
CREATE TABLE IF NOT EXISTS ai.sessions (
    session_id   text NOT NULL,
    model_id     text NOT NULL,
    node_id      text NOT NULL,
    instance_id  uuid NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL,
    PRIMARY KEY (session_id, model_id)
);

CREATE INDEX IF NOT EXISTS sessions_expiry ON ai.sessions (expires_at);
CREATE INDEX IF NOT EXISTS sessions_instance ON ai.sessions (instance_id);

-- ---------------------------------------------------------------------------
-- Model events and result cache
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ai.model_events (
    id           bigserial PRIMARY KEY,
    node_id      text NOT NULL,
    model_id     text NOT NULL,
    instance_id  uuid,
    -- load_started, ready, load_failed, parked, woken, stopped, crashed,
    -- evicted, preempted_jobs
    event        text NOT NULL,
    detail       jsonb NOT NULL DEFAULT '{}'::jsonb,
    at           timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS model_events_at ON ai.model_events (at);

CREATE TABLE IF NOT EXISTS ai.result_cache (
    -- sha256 of model id, model version and the canonical input.
    key         text PRIMARY KEY,
    model_id    text NOT NULL,
    output      jsonb NOT NULL,
    hits        bigint NOT NULL DEFAULT 0,
    created_at  timestamptz NOT NULL DEFAULT now(),
    expires_at  timestamptz
);

CREATE INDEX IF NOT EXISTS result_cache_expiry
    ON ai.result_cache (expires_at)
    WHERE expires_at IS NOT NULL;
